arguments.command:
cd /work; D=../data/current.db; sqlite3 -header $D "
select 'ops_no_attempt', count(*) from logical_operations o where not exists(select 1 from attempt_events a where a.operation_id=o.operation_id);
select 'ops_no_assign', count(*) from logical_operations o where not exists(select 1 from route_assignments r where r.route_id=o.route_id and o.opened_at_ms>=r.effective_from_ms and o.opened_at_ms<r.effective_to_ms);
select 'ops_multi_assign', count(*) from logical_operations o join route_assignments r on r.route_id=o.route_id and o.opened_at_ms>=r.effective_from_ms and o.opened_at_ms<r.effective_to_ms group by o.operation_id having count(*)>1;
select 'attempt_seq_gaps', count(*) from (select operation_id, max(attempt_no) m, count(*) c from attempt_events group by operation_id having m<>c);
select 'orphan_route', count(*) from logical_operations o where route_id not in (select route_id from service_routes);
select 'window1', count(*) from logical_operations where opened_at_ms>=1777852800000 and opened_at_ms<1777856400000;
select 'window2', count(*) from logical_operations where opened_at_ms>=1777939200000 and opened_at_ms<1777942800000;
select datetime(1777856400000/1000,'unixepoch'), datetime(1777942800000/1000,'unixepoch');
select 'min_max_ops_by_route', route_id, count(*) from logical_operations group by route_id;
select 'dup_opid_tenant', count(*) from logical_operations o join tenants t using(tenant_id);
"

